function harmonizeProcess(samples, semitones, mix){
  mix = mix != null ? mix : 0.5;
  var r = Math.pow(2, semitones/12);
  var n = samples.length;
  var out = new Array(n);
  for(var i=0;i<n;i++){
    var pos = i * r;
    var i0 = Math.floor(pos);
    if(i0 < 0) i0 = 0;
    if(i0 > n-1) i0 = n-1;
    var i1 = i0 + 1; if(i1 > n-1) i1 = n-1;
    var f = (i0 >= n-1) ? 0 : (pos - i0);
    var shifted = samples[i0]*(1-f) + samples[i1]*f;
    out[i] = samples[i]*(1-mix) + shifted*mix;
  }
  return out;
}
function harmonizeAnalyze(samples, semitones, mix){
  var out = harmonizeProcess(samples, semitones, mix);
  var peak=0, sum=0;
  for(var i=0;i<out.length;i++){ var a=Math.abs(out[i]); if(a>peak)peak=a; sum+=out[i]*out[i]; }
  return { length: out.length, ratio: Math.pow(2, semitones/12), peak: peak, rms: Math.sqrt(sum/out.length) };
}

var EXPORTS={harmonizeAnalyze:harmonizeAnalyze,harmonizeProcess:harmonizeProcess};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.HarmonizerForgePure = EXPORTS; }
